        getChangeIdsSnapshot: vi.fn(() => [...changes.keys()]),
        getEdgeIdsSnapshot: vi.fn(() => [...edges.keys()]),
        getEdgeSnapshot: vi.fn((edgeId: string) => edges.get(edgeId) ?? null),
        getGroupIdsSnapshot: vi.fn(() => [...groups.keys()]),
